from __future__ import annotations

import base64
import io
import os
import sys
import zipfile
from pathlib import Path

root = Path(sys.argv[1]).resolve()
payload = """"""
data = base64.b64decode(payload, validate=True)

expected = {
    "3e_j_r2_operation_manual.md",
    "authorization/ai-media-os-3e-j-root-helper.sudoers",
    "authorization/sudo-command-contract.json",
    "blocked-deployment-planner.py",
    "deployment-contract.json",
    "docs/3e_j_operation_manual.md",
    "r2-candidate-manifest.json",
    "review/test_3e_j_runner_negative.py",
    "review/validate_3e_j_runner_packet.py",
    "runtime/one_shot_writer_freeze_backup_restart_runner.py",
    "runtime/root_fd_metadata_helper.py",
    "runtime/runner-policy.json",
    "test_3e_j_r2_deployment_authorization_negative.py",
    "validate_3e_j_r2_deployment_authorization_packet.py",
}

with zipfile.ZipFile(io.BytesIO(data), "r") as archive:
    names = set(archive.namelist())
    assert names == expected
    for member in archive.infolist():
        assert not member.is_dir()
        target = (root / member.filename).resolve()
        assert root == target or root in target.parents
        target.parent.mkdir(parents=True, exist_ok=True)
        descriptor = os.open(
            target,
            os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
            0o640,
        )
        with os.fdopen(descriptor, "wb", closefd=True) as stream:
            stream.write(archive.read(member))
            stream.flush()
            os.fsync(stream.fileno())

print("R2_CANDIDATE_PAYLOAD_DECODE=PASS")
print(f"R2_CANDIDATE_FILE_COUNT={len(expected)}")
PY

# Read-only current-host inventory. Raw sudo -n -l output is never saved.
"$PYTHON_BIN" - \
  "$REPO_ROOT" \
  "$INVENTORY_ROOT" \
  "$CANDIDATE_ROOT/deployment-contract.json" \
  "$CANDIDATE_ROOT/authorization/sudo-command-contract.json" <<'PY'
from __future__ import annotations

import grp
import json
import os
import pwd
import stat
import subprocess
import sys
from collections import Counter
from pathlib import Path
from typing import Any

repo = Path(sys.argv[1]).resolve()
inventory_root = Path(sys.argv[2]).resolve()
contract_path = Path(sys.argv[3]).resolve()
command_contract_path = Path(sys.argv[4]).resolve()

contract = json.loads(contract_path.read_text(encoding="utf-8"))
command_contract = json.loads(
    command_contract_path.read_text(encoding="utf-8")
)

def identity(uid: int, gid: int) -> tuple[str, str]:
    try:
        owner = pwd.getpwuid(uid).pw_name
    except KeyError:
        owner = str(uid)
    try:
        group = grp.getgrgid(gid).gr_name
    except KeyError:
        group = str(gid)
    return owner, group

def metadata(path: Path) -> dict[str, Any]:
    try:
        item = path.lstat()
    except FileNotFoundError:
        return {
            "path": str(path),
            "name": path.name,
            "exists": False,
            "existence_state": "ABSENT_CONFIRMED",
            "metadata_accessible": True,
            "is_symlink": False,
            "metadata_error": None,
        }
    except PermissionError as exc:
        return {
            "path": str(path),
            "name": path.name,
            "exists": None,
            "existence_state": "UNKNOWN_PERMISSION_DENIED",
            "metadata_accessible": False,
            "is_symlink": None,
            "metadata_error": f"PermissionError:{exc.errno}",
        }
    except OSError as exc:
        return {
            "path": str(path),
            "name": path.name,
            "exists": None,
            "existence_state": "UNKNOWN_OS_ERROR",
            "metadata_accessible": False,
            "is_symlink": None,
            "metadata_error": (
                f"OSError:{exc.errno}:{type(exc).__name__}"
            ),
        }

    owner, group = identity(item.st_uid, item.st_gid)
    mode = stat.S_IMODE(item.st_mode)
    return {
        "path": str(path),
        "name": path.name,
        "exists": True,
        "existence_state": "PRESENT_CONFIRMED",
        "metadata_accessible": True,
        "is_symlink": stat.S_ISLNK(item.st_mode),
        "is_directory": stat.S_ISDIR(item.st_mode),
        "is_regular_file": stat.S_ISREG(item.st_mode),
        "owner": owner,
        "group": group,
        "uid": item.st_uid,
        "gid": item.st_gid,
        "mode": f"{mode:04o}",
        "group_or_other_writable": bool(mode & 0o022),
        "metadata_error": None,
    }

def write_json(name: str, payload: Any) -> None:
    (inventory_root / name).write_text(
        json.dumps(payload, ensure_ascii=False, sort_keys=True, indent=2)
        + "\n",
        encoding="utf-8",
    )

repo_paths = [
    repo,
    repo / "scripts",
    repo / "scripts/manual",
    repo / "exchange",
    repo / "exchange/review_evidence",
]
repo_inventory = {
    "schema_version": "1.0",
    "paths": [metadata(path) for path in repo_paths],
}

manual_dir = repo / "scripts/manual"
manual_entries = []
if manual_dir.is_dir():
    for entry in sorted(manual_dir.iterdir(), key=lambda item: item.name):
        item = metadata(entry)
        if item["exists"]:
            manual_entries.append(item)

repo_inventory["manual_script_rules"] = {
    "directory": metadata(manual_dir),
    "entry_count": len(manual_entries),
    "regular_file_count": sum(
        1 for item in manual_entries if item.get("is_regular_file")
    ),
    "directory_count": sum(
        1 for item in manual_entries if item.get("is_directory")
    ),
    "mode_distribution": dict(
        Counter(item.get("mode") for item in manual_entries)
    ),
    "owner_distribution": dict(
        Counter(item.get("owner") for item in manual_entries)
    ),
    "group_distribution": dict(
        Counter(item.get("group") for item in manual_entries)
    ),
    "suffix_distribution": dict(
        Counter(Path(item["name"]).suffix for item in manual_entries)
    ),
    "sample_names": [
        item["name"] for item in manual_entries[:40]
    ],
    "file_contents_read": False,
}
write_json("repository-layout-inventory.json", repo_inventory)

sudo_metadata = {
    "schema_version": "1.0",
    "sudoers": metadata(Path("/etc/sudoers")),
    "sudoers_d": metadata(Path("/etc/sudoers.d")),
    "sudoers_d_entries": [],
    "contents_read": False,
}
sudoers_d = Path("/etc/sudoers.d")
try:
    if sudoers_d.is_dir():
        sudo_metadata["sudoers_d_entries"] = [
            metadata(entry)
            for entry in sorted(
                sudoers_d.iterdir(),
                key=lambda item: item.name,
            )
        ]
except PermissionError as exc:
    sudo_metadata["metadata_scan_error"] = (
        f"PermissionError:{exc.errno}"
    )
except OSError as exc:
    sudo_metadata["metadata_scan_error"] = (
        f"OSError:{exc.errno}:{type(exc).__name__}"
    )
write_json("sudoers-metadata-inventory.json", sudo_metadata)

helper_path = command_contract["helper_path"]
exact_commands = [
    item["sudoers_command"]
    for item in command_contract["allowed_commands"]
]
sudo_path = shutil_which = None
try:
    import shutil
    sudo_path = shutil.which("sudo")
    visudo_path = shutil.which("visudo")
except Exception:
    visudo_path = None

sudo_result = {
    "schema_version": "1.0",
    "sudo_command_path": sudo_path,
    "visudo_command_path": visudo_path,
    "sudo_list_invoked": False,
    "sudo_list_exit_code": None,
    "sudo_list_query_succeeded": False,
    "raw_sudo_list_saved": False,
    "exact_helper_path_match_count": 0,
    "exact_helper_matching_lines": [],
    "exact_command_authorized": {
        command: False for command in exact_commands
    },
}
if sudo_path:
    completed = subprocess.run(
        [sudo_path, "-n", "-l"],
        text=True,
        capture_output=True,
        check=False,
        timeout=20,
    )
    sudo_result["sudo_list_invoked"] = True
    sudo_result["sudo_list_exit_code"] = completed.returncode
    sudo_result["sudo_list_query_succeeded"] = (
        completed.returncode == 0
    )
    combined = completed.stdout.splitlines() + completed.stderr.splitlines()
    matching = [
        " ".join(line.split())
        for line in combined
        if helper_path in line
    ]
    sudo_result["exact_helper_matching_lines"] = matching
    sudo_result["exact_helper_path_match_count"] = len(matching)
    for command in exact_commands:
        sudo_result["exact_command_authorized"][command] = any(
            command in line for line in matching
        )
write_json("sudo-readonly-inventory.json", sudo_result)

planned_paths = []
for record in contract["directories"]:
    planned_paths.append(metadata(Path(record["path"])))
for record in contract["artifacts"]:
    planned_paths.append(metadata(Path(record["destination"])))
planned_paths.append(metadata(Path(contract["sudoers"]["destination"])))

# Deduplicate while preserving order.
seen = set()
deduplicated = []
for item in planned_paths:
    if item["path"] in seen:
        continue
    seen.add(item["path"])
    deduplicated.append(item)

opt_state = metadata(Path("/opt"))
artifact_destination_states = [
    metadata(Path(record["destination"]))
    for record in contract["artifacts"]
]
artifact_destinations_absent = all(
    item["existence_state"] == "ABSENT_CONFIRMED"
    and item["is_symlink"] is False
    for item in artifact_destination_states
)
artifact_destination_metadata_complete = all(
    item["metadata_accessible"] is True
    for item in artifact_destination_states
)

sudoers_destination = Path(contract["sudoers"]["destination"])
sudoers_destination_state = metadata(sudoers_destination)
sudoers_destination_absent = (
    sudoers_destination_state["existence_state"]
    == "ABSENT_CONFIRMED"
    and sudoers_destination_state["is_symlink"] is False
)
sudoers_destination_metadata_complete = (
    sudoers_destination_state["metadata_accessible"] is True
)
opt_parent_safe = (
    opt_state.get("exists") is True
    and opt_state.get("is_directory") is True
    and opt_state.get("is_symlink") is False
    and opt_state.get("owner") == "root"
    and opt_state.get("group_or_other_writable") is False
)
deployment_root = Path(contract["deployment_root"]["path"])
deployment_root_state = metadata(deployment_root)
deployment_root_current_safe = (
    deployment_root_state["existence_state"] == "ABSENT_CONFIRMED"
    or (
        deployment_root_state["existence_state"] == "PRESENT_CONFIRMED"
        and deployment_root_state.get("is_directory") is True
